#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# Fase 8h -- CONSOLIDA las Fases 8f + 8g en un único script.
#
# Causa del error de build que acabas de ver:
#   src/modules/routes/routes.routes.ts(377,36): error TS2339: Property
#   'orsMaxOptimizationVehicles' does not exist on type '...'
#
# routes.routes.ts (Fase 8g, varias pasadas de planificación) usa
# env.orsMaxOptimizationVehicles, una propiedad que se añadió a env.ts en un
# script ANTERIOR y separado (Fase 8f). Si ese script no llegó a aplicarse
# (o se aplicó sobre un checkout que luego se descartó), routes.routes.ts
# queda con una referencia a algo que env.ts no tiene -- de ahí el error.
#
# Para que esto no pueda volver a pasar, este script sustituye a la vez a
# apply_fase8f_limite_vehiculos_ors.sh Y a apply_fase8g_pasadas_multiples.sh:
# trae los DOS ficheros ya consistentes entre sí. No hace falta (ni hace
# falta reaplicar) ninguno de esos dos scripts anteriores -- basta con este.
# Es seguro ejecutarlo aunque ya hubieras aplicado alguno de los dos: deja
# ambos ficheros en su versión final correcta de todas formas.
# ============================================================================

TARGET_DIR="${1:-.}"
cd "$TARGET_DIR"

echo "Aplicando Fase 8h (consolidado 8f+8g) sobre: $(pwd)"
echo

FILES_APPLIED=(
  "backend/src/config/env.ts"
  "backend/src/modules/routes/routes.routes.ts"
)

echo "-> backend/src/config/env.ts"
mkdir -p "$(dirname "backend/src/config/env.ts")"
base64 -d > "backend/src/config/env.ts" <<'B64EOF_backend_src_config_env_ts'

B64EOF_backend_src_config_env_ts

echo "-> backend/src/modules/routes/routes.routes.ts"
mkdir -p "$(dirname "backend/src/modules/routes/routes.routes.ts")"
base64 -d > "backend/src/modules/routes/routes.routes.ts" <<'B64EOF_backend_src_modules_routes_routes_routes_ts'

B64EOF_backend_src_modules_routes_routes_routes_ts

echo
echo "Fase 8h aplicada correctamente."
echo "Ficheros actualizados:"
for f in "${FILES_APPLIED[@]}"; do
  echo "  - $f"
done
